'use strict';
window.RealMission={ready:false,terrain:null,radius:3000,margin:.5,panelHeight:1};
const RM=window.RealMission,C=LunarRealCore,oldUpdateReal=update,oldHorizonReal=horizon,oldEvaluateReal=evaluate,oldRenderReal=renderMission,oldAnalysisReal=missionAnalysis;
function realProfile(s,h){return RM.terrain.profile(s,h,RM.radius);}
horizon=function(s,az,h){if(!RM.ready)return oldHorizonReal(s,az,h);return RM.terrain.angle(realProfile(s,h),az);};
evaluate=function(s,row,h){if(!RM.ready)return oldEvaluateReal(s,row,h);const info=RM.terrain.inspect(s,RM.radius);if(!info.covered)throw Error('Ubicación fuera de la cobertura de Site01.');const earth=C.direction(s,row.subearth,row.distance*1000,info.elevation,h),sun=C.direction(s,row.subsolar,1e15,info.elevation,RM.panelHeight),eh=horizon(s,earth.az,h),sh=horizon(s,sun.az,RM.panelHeight),estate=C.state(earth.el,eh,RM.margin),sstate=C.state(sun.el,sh,RM.margin);return{earth,sun,ev:estate==='clear',sv:sstate==='clear',estate,sstate,earthHorizon:eh,sunHorizon:sh,groundM:info.elevation,antennaM:h,panelM:RM.panelHeight,source:'LOLA Site01 + NASA SVS; spherical approximation',radiusM:RM.radius,marginDeg:RM.margin};};
missionAnalysis=function(...args){return RM.ready?oldAnalysisReal(...args):null;};
function realEventText(arr,key){const q=C.nextEvent(arr,key),name=key==='sv'?'Sol':'Tierra';return q.hours===null?`${name}: sin cambio confirmado dentro de las próximas ${arr.length} h.`:`${name}: ${q.now?'se pierde la ventana confirmada':'próxima ventana confirmada'} en ≈${q.hours} h. Eventos entre muestras de 1 h.`;}
function realWindowCard(arr){return `<div class="real-countdowns"><article><span>☼ TU PRÓXIMA VENTANA DE LUZ</span><b>${realEventText(arr,'sv')}</b></article><article><span>◎ TU PRÓXIMO CONTACTO POSIBLE</span><b>${realEventText(arr,'ev')}</b></article></div><p class="game-small">“Confirmada” significa que supera el horizonte muestreado por más del margen elegido (${RM.margin}°), dentro de ${RM.radius/1000} km. Las horas marginales cuentan como no confirmadas; el relieve lejano puede añadir obstáculos.</p>`;}
horizonMarkup=function(s,h,c){if(!RM.ready)return '';const ep=realProfile(s,h),sp=realProfile(s,RM.panelHeight),min=Math.floor(Math.min(-8,c.earth.el,c.sun.el,...ep.rows.map(q=>q.el),...sp.rows.map(q=>q.el))-2),max=Math.ceil(Math.max(8,c.earth.el,c.sun.el,...ep.rows.map(q=>q.el),...sp.rows.map(q=>q.el))+2),x=a=>44+a/360*525,y=a=>225-(a-min)/(max-min)*195;let out='';for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;out+=`<path d="M44 ${y(v)}H570" stroke="#34506a"/><text x="2" y="${y(v)+4}">${v.toFixed(0)}°</text>`;}out+=`<path d="M44 225L${ep.rows.map(q=>x(q.az)+' '+y(q.el)).join(' L')}L570 ${y(ep.rows[0].el)}V225Z" fill="#49657788"/><path d="M${sp.rows.map(q=>x(q.az)+' '+y(q.el)).join(' L')}" fill="none" stroke="#e6c878" stroke-dasharray="5 4"/>`;for(const[p,col,name]of[[c.earth,'#78d9ee','Tierra'],[c.sun,'#f5d26d','Sol']])out+=`<circle cx="${x(p.az)}" cy="${y(p.el)}" r="7" fill="${col}"/><text x="${Math.min(460,Math.max(44,x(p.az)+8))}" y="${Math.max(18,y(p.el)-13)}" style="fill:${col}">${name} ${p.el.toFixed(1)}°</text>`;for(const a of[0,90,180,270,360])out+=`<text x="${x(a)-7}" y="251">${a}°</text>`;return out+`<text x="44" y="276">LOLA · antena ${h} m · panel ${RM.panelHeight} m · radio ${RM.radius/1000} km</text>`;};
update=function(){if(!RM.ready||!records.length)return;oldUpdateReal();const c=current;if(RM.lastUISite!==$('site').value&&$('technicalLon')){RM.lastUISite=$('site').value;$('technicalLon').value=sites[+$('site').value].lon.toFixed(6);$('technicalLat').value=sites[+$('site').value].lat.toFixed(6);}$('earthState').textContent=c.ev?'Ventana confirmada':c.estate==='uncertain'?'Cerca del horizonte':'Sin ventana confirmada';$('sunState').textContent=c.sv?'Ventana confirmada':c.sstate==='uncertain'?'Cerca del horizonte':'Sin ventana confirmada';$('insight').textContent='Terreno real de Site01. '+realEventText(series,'ev')+' Visibilidad no garantiza servicio de radio.';$('energyInsight').textContent+=' Estimación conservadora sobre LOLA; no incluye temperatura.';if($('realNow'))$('realNow').innerHTML=realWindowCard(series);window.dispatchEvent(new Event('real-scenario-change'));};
function siteChoices(){for(const id of['site','compareSiteA','compareSiteB']){const prev=$(id).value;$(id).replaceChildren(...sites.map((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=s.name;return o;}));$(id).value=String(Math.min(+prev,sites.length-1));}}
function pickRealSite(lon,lat){const s={name:'Site01 · Tu ubicación',lon:+lon,lat:+lat,real:true},info=RM.terrain.inspect(s,RM.radius);if(!Number.isFinite(s.lon)||!Number.isFinite(s.lat)||s.lat<-90||s.lat>90||s.lon<-180||s.lon>180)throw Error('Ingresá latitud −90…90 y longitud este −180…180.');if(!info.covered)throw Error(`Ese punto no tiene un círculo completo de ${RM.radius/1000} km dentro del DEM. Elegí un punto más central en Site01; no completamos zonas sin datos.`);if(sites.length>3)sites[3]=s;else sites.push(s);siteChoices();mission.site=3;$('site').value='3';missionFeedback=assessDecision('site',null,missionAnalysis());guideStep=-1;guideTipIndex=0;renderMission();update();return info;}
window.pickRealSite=pickRealSite;
function customForm(publicMode){const p=publicMode?'public':'technical',s=sites[publicMode?mission.site:+$('site').value];return `<details class="real-custom"><summary>¿Querés elegir tu propio punto? ↗</summary><p>Podés tocar el relieve 3D o ingresar coordenadas dentro del área real de Site01. Fuera del mapa mostramos falta de cobertura.</p><div class="real-coordinate-fields"><label>Longitud este (°)<input id="${p}Lon" type="number" step="0.00001" min="-180" max="180" value="${s.lon.toFixed(6)}"></label><label>Latitud (°)<input id="${p}Lat" type="number" step="0.00001" min="-90" max="90" value="${s.lat.toFixed(6)}"></label><button data-custom-mode="${p}">Evaluar mi punto →</button></div><p id="${p}CoordStatus" role="status"></p></details>`;}
function bindRealControls(){document.querySelectorAll('[data-open-real3d]').forEach(b=>b.onclick=()=>openReal3D());document.querySelectorAll('[data-custom-mode]').forEach(b=>b.onclick=()=>{const p=b.dataset.customMode;try{pickRealSite($(p+'Lon').value,$(p+'Lat').value);toast('Ubicación aplicada al mismo modelo de misión.');}catch(e){$(p+'CoordStatus').textContent=e.message;}});document.querySelectorAll('[data-open-usability]').forEach(b=>b.onclick=()=>$('usabilityDialog').showModal());}
renderMission=function(){oldRenderReal();if(!RM.ready){$('gameNext').disabled=true;document.querySelectorAll('[data-journey]').forEach(b=>b.disabled=true);if(!$('publicMission').hidden)setGuideBubble('terrain','Estamos preparando el terreno real.','Descargamos el mapa LOLA de Site01 para que tus elecciones se calculen sobre las mismas alturas.');return;}if(journeyStarted&&mission.step===1){document.querySelector('.stage-heading').insertAdjacentHTML('afterend',`<section class="real-friendly"><span class="eyebrow">TRES LUGARES DEL MISMO TERRENO REAL</span><h2>Miralo, giralo y elegí.</h2><p>Ahora los tres puntos se calculan sobre Site01, en el polo sur lunar. El verde marca menor pendiente, no un aterrizaje aprobado.</p><button data-open-real3d class="primary">⛶ Explorar las alturas en 3D</button>${customForm(true)}</section>`);}document.querySelectorAll('#gameContent [data-action=site]').forEach(b=>{const q=RM.terrain.inspect(sites[+b.dataset.value],RM.radius);b.insertAdjacentHTML('beforeend',`<span class="real-slope-badge">Pendiente máxima de celda: ${q.slope.toFixed(1)}° · ${q.elevation.toFixed(0)} m de altura</span>`);});const a=missionAnalysis();if(journeyStarted&&a&&mission.step>0){$('gameContent').insertAdjacentHTML('beforeend','<section id="realPublicWindows">'+realWindowCard(a.samples.slice(mission.previewHour))+'</section>');const uncertain=a.samples.filter(s=>s.estate==='uncertain'||s.sstate==='uncertain').length;$('gameContent').insertAdjacentHTML('beforeend',`<p class="game-small">${uncertain} horas tienen al menos una dirección cerca del horizonte. Se usa el mismo cálculo en el juego y el laboratorio; las posiciones astronómicas son aproximadas.</p>`);}if(!journeyStarted||mission.step===6)$('gameContent').insertAdjacentHTML('beforeend','<button class="real-test-link" data-open-usability>✦ Ayudanos a probar: tres pequeños retos</button>');if($('gameTime')){const onTime=$('gameTime').oninput;$('gameTime').oninput=e=>{onTime(e);const a=missionAnalysis();$('realPublicWindows').innerHTML=realWindowCard(a.samples.slice(mission.previewHour));updateRealSky(a.samples[mission.previewHour]);};}if(a&&journeyStarted)updateRealSky(a.samples[mission.previewHour]);if($('downloadMission'))$('downloadMission').onclick=()=>exportReal(true);bindRealControls();};
function summaryComparison(){const A=selectedIndex($('compareDateA')),B=selectedIndex($('compareDateB')),h=number('compareHeight'),aa=records.slice(A,A+168).map(r=>evaluate(sites[+$('compareSiteA').value],r,h)),bb=records.slice(B,B+168).map(r=>evaluate(sites[+$('compareSiteB').value],r,h)),p={capacityWh:number('battery'),initialFraction:1,tracking:$('solarTracking').value==='tracking',azimuth:number('panelAzimuth'),tilt:number('panelTilt'),areaM2:number('panelArea'),efficiency:number('panelEfficiency')/100,lossFraction:number('panelLoss')/100,irradiance:1361,stepHours:1,loadW:number('load'),chargeEfficiency:number('chargeEfficiency')/100},ea=solarBudget(aa,p),eb=solarBudget(bb,p),ds=visibleHours(bb,'sv')-visibleHours(aa,'sv'),de=visibleHours(bb,'ev')-visibleHours(aa,'ev');$('compareVerdict').textContent=`B frente a A: ${ds>=0?'+':''}${ds} h de luz confirmada; ${de>=0?'+':''}${de} h de Tierra visible confirmada. Demanda eléctrica sin cubrir: A ${Math.round(ea.unservedWh)} Wh, B ${Math.round(eb.unservedWh)} Wh con los mismos parámetros energéticos. ${ds*de<0?'Hay un intercambio entre luz y comunicaciones: elegí tu prioridad.':'Revisá también las horas continuas de sombra y los cortes.'} Horizonte real muestreado hasta ${RM.radius/1000} km; posiciones NASA aproximadas.`;}
const baseCompareReal=drawCompare;drawCompare=function(){if(!RM.ready)return;baseCompareReal();summaryComparison();};
function mountTechnical(){const controls=document.createElement('section');controls.className='panel real-controls';controls.id='realControls';controls.innerHTML=`<div class="panelhead"><h2>Un solo modelo para tu misión</h2><span class="pill">LOLA SITE01 · DATOS REALES</span></div><p>Elegir sitio y fecha recalcula el horizonte, la luz, las comunicaciones y el balance energético. Funciona en el navegador.</p><div class="real-coordinate-fields"><label>Radio de horizonte (m)<select id="realRadius"><option value="1000">1.000</option><option value="2000">2.000</option><option value="3000" selected>3.000</option></select></label><label>Margen angular de diseño (°)<input id="realMargin" type="number" min="0" max="5" step="0.1" value="0.5"></label><label>Altura del panel (m)<input id="realPanelHeight" type="number" min="0.5" max="30" step="0.5" value="1"></label><button data-open-real3d>⛶ Luna y terreno 3D</button></div><p id="realSettingsStatus" role="status"></p><div id="technicalCoordinates"></div><div id="realNow"></div><p class="footnote">DEM nativo 5 m, agregado a 20 m; horizonte cada 2° y 20 m radiales. Se usa el máximo de cada bloque para reducir subestimaciones, sin garantizar detectar todo obstáculo. El margen es un supuesto, no una incertidumbre medida. Relieve fuera del radio, rocas y errores del DEM no están resueltos.</p>`;$('missionControls').before(controls);for(const id of['realRadius','realMargin','realPanelHeight'])$(id).onchange=()=>{if(['realMargin','realPanelHeight'].some(q=>!$(q).checkValidity()||!$(q).value)){$('realSettingsStatus').textContent='Revisá los valores: margen de 0 a 5° y panel de 0,5 a 30 m.';return;}$('realSettingsStatus').textContent='Parámetros aplicados al mismo modelo.';const radius=+$('realRadius').value;if(sites.some(s=>!RM.terrain.inspect(s,radius).covered)){toast('El punto personalizado no tiene cobertura para ese radio. Elegí un punto más central.');$('realRadius').value=RM.radius;return;}RM.radius=radius;RM.margin=number('realMargin');RM.panelHeight=number('realPanelHeight');update();renderMission();};}
mountTechnical();
const loadFloat=async file=>{const r=await fetch('assets/site01/'+file+'.f32');if(!r.ok)throw Error('No se pudo cargar '+file);return new Float32Array(await r.arrayBuffer());};
Promise.all([fetch('assets/site01/metadata.json').then(r=>{if(!r.ok)throw Error('Metadatos LOLA no disponibles');return r.json();}),loadFloat('mean'),loadFloat('peak'),loadFloat('slope')]).then(([meta,m,p,s])=>{RM.terrain=C.makeTerrain(meta,m,p,s);sites.splice(0,sites.length,...RM.terrain.presets());RM.ready=true;siteChoices();$('technicalCoordinates').innerHTML=customForm(false);document.querySelector('.notice').innerHTML='<span>◈</span><div><b>LOLA real + NASA SVS 2025–2026.</b> Un mismo modelo para juego y laboratorio. Cobertura limitada a Site01 y al radio indicado; no es una herramienta de vuelo.</div>';$('terrain').insertAdjacentHTML('afterbegin','<section class="panel real-friendly"><h2>Las alturas se convierten en relieve 3D</h2><p>Solo Site01 real. Los 24 sitios simulados del archivo original no se usan para evaluar misiones.</p><button data-open-real3d class="primary">⛶ Abrir Luna y relieve real</button></section>');$('realControls').insertAdjacentHTML('beforeend','<p class="footnote" id="realValidation">Verificación: geometría esférica, cobertura y contraste con muestras JPL documentados en metodología.</p>');bindRealControls();renderMission();update();window.dispatchEvent(new Event('real-terrain-ready'));}).catch(e=>{$('connection').textContent='Error de terreno real';$('gameContent').textContent='No pudimos preparar el terreno: '+e.message;$('gameNext').disabled=true;toast(e.message);});
window.addEventListener('lunar-data-ready',()=>{if(RM.ready){update();renderMission();}});

const oldAssessReal=assessDecision;
assessDecision=function(key,before,after){const f=oldAssessReal(key,before,after);if(f&&key==='site'&&RM.ready){const q=RM.terrain.inspect(sites[mission.site],RM.radius);if(q.slope>10){f.kind='caution';f.title='Más luz no significa un suelo adecuado.';f.reason=`La celda alcanza ${q.slope.toFixed(1)}° y supera el criterio ilustrativo de 10°. Podés explorar luz y comunicaciones, pero esta elección no cumple ese filtro de pendiente. Tampoco evaluamos rocas ni rugosidad subpíxel.`;}}return f;};
function exportReal(publicMode){const idx=publicMode?missionIndex():dateIndex(),si=publicMode?mission.site:+$('site').value,h=publicMode?mission.height:number('height'),samples=records.slice(idx,idx+168).map(r=>evaluate(sites[si],r,h));download('los-lunares-escenario-real.json',JSON.stringify({educational:true,site:sites[si],utc:new Date(Date.UTC(2025,0,1,idx)).toISOString(),terrain:RM.terrain.meta,model:{radiusM:RM.radius,azimuthStepDeg:2,radialStepM:20,marginDeg:RM.margin,antennaM:h,panelM:RM.panelHeight,temporalStepH:1,ephemeris:'NASA SVS 5415/5587 spherical approximation'},sunConfirmedHours:visibleHours(samples,'sv'),earthConfirmedHours:visibleHours(samples,'ev'),events:{sun:C.nextEvent(samples,'sv'),earth:C.nextEvent(samples,'ev')},comparison:comparisonSnapshot(),energy:publicMode?missionAnalysis().budget:{capacityWh:number('battery'),loadW:number('load')},choices:publicMode?mission:undefined,samples,limitations:['Horizon only within stated radius and sampled resolution','No per-pixel uncertainty propagation','No flight or landing certification','No full radio, thermal, solar disk or eclipse model']},null,2),'application/json');}
$('export').onclick=()=>RM.ready?exportReal(false):toast('Esperá a que cargue LOLA.');

function updateRealSky(c){const box=document.querySelector('#gameContent .game-sky-status');if(!box)return;for(const [key,caption,state]of [['sunlight','☼ Sol',c.sstate],['earth','◎ Tierra',c.estate]]){const b=box.querySelector('[data-fact='+key+']');if(b)b.textContent=caption+' · '+(state==='clear'?'ventana confirmada':state==='uncertain'?'cerca del horizonte':'sin ventana confirmada')+' · tocar para aprender';}}
